#!/usr/bin/env bash
# Build the th06 (东方红魔乡) portable branch to WebAssembly via emscripten.
#
# Prereqcuisites:
#   - emsdk installed and activated:  source ~/emsdk/emsdk_env.sh
#   - src/autogenerated/Embeds.hpp present (generated by a prior native premake build,
#     or regenerate with: premake5 gmake)
#
# Output: dist/th06.{html,js,wasm} under the project directory.
set -euo pipefail

PROJ="${TH06_PORTABLE_DIR:-$HOME/projects/th06-portable}"
SRC="$PROJ/src"
OUT="$PROJ/dist"

if ! command -v emcc >/dev/null 2>&1; then
  echo "error: emcc not found. Run: source ~/emsdk/emsdk_env.sh" >&2
  exit 1
fi

if [ ! -f "$SRC/autogenerated/Embeds.hpp" ]; then
  echo "error: $SRC/autogenerated/Embeds.hpp missing. Run a native 'premake5 gmake' first." >&2
  exit 1
fi

mkdir -p "$OUT"

# DEBUG=1 enables assertions + readable stack traces to diagnose aborts.
if [ "${DEBUG:-0}" = "1" ]; then
  OPT_FLAGS=(-O0 -g -sASSERTIONS=2 -sSAFE_HEAP=0 -sSTACK_OVERFLOW_CHECK=2 -sGL_ASSERTIONS=1 -sGL_DEBUG=1)
else
  OPT_FLAGS=(-O2)
fi

# Source files mirror premake5.lua's file list. MIDI falls through to the
# MidiDefault (silent) backend since no win/linux/mac os.target matches under emscripten.
SOURCES=(
  "$SRC"/AnmManager.cpp
  "$SRC"/AsciiManager.cpp
  "$SRC"/BombData.cpp
  "$SRC"/BulletData.cpp
  "$SRC"/BulletManager.cpp
  "$SRC"/Chain.cpp
  "$SRC"/Controller.cpp
  "$SRC"/EclManager.cpp
  "$SRC"/EffectManager.cpp
  "$SRC"/Ending.cpp
  "$SRC"/EnemyEclInstr.cpp
  "$SRC"/EnemyManager.cpp
  "$SRC"/FileSystem.cpp
  "$SRC"/GameErrorContext.cpp
  "$SRC"/GameManager.cpp
  "$SRC"/GameWindow.cpp
  "$SRC"/Gui.cpp
  "$SRC"/ItemManager.cpp
  "$SRC"/main.cpp
  "$SRC"/MainMenu.cpp
  "$SRC"/MidiOutput.cpp
  "$SRC"/MusicRoom.cpp
  "$SRC"/Player.cpp
  "$SRC"/ReplayManager.cpp
  "$SRC"/ResultScreen.cpp
  "$SRC"/Rng.cpp
  "$SRC"/ScreenEffect.cpp
  "$SRC"/SoundPlayer.cpp
  "$SRC"/Stage.cpp
  "$SRC"/Supervisor.cpp
  "$SRC"/TextHelper.cpp
  "$SRC"/ZunMath.cpp
  "$SRC"/utils.cpp
  "$SRC"/ZunTimer.cpp
  "$SRC"/graphics/GLFunc.cpp
  "$SRC"/graphics/FixedFunctionGL.cpp
  "$SRC"/graphics/WebGL.cpp
  "$SRC"/graphics/Software.cpp
  "$SRC"/pbg3/FileAbstraction.cpp
  "$SRC"/pbg3/IPbg3Parser.cpp
  "$SRC"/pbg3/Pbg3Archive.cpp
  "$SRC"/pbg3/Pbg3Parser.cpp
  "$SRC"/midi/MidiDefault.cpp
  "$SRC"/thirdparty/sjis_converter.cpp
)

# --preload-file is added later (Phase 3) once game .DAT assets are available.
PRELOAD=()
if [ -d "${TH06_ASSETS_DIR:-}" ]; then
  echo "Preloading assets from $TH06_ASSETS_DIR -> virtual FS root"
  PRELOAD=(--preload-file "$TH06_ASSETS_DIR@/")
fi

set -x
emcc \
  -std=c++20 \
  -I"$SRC" \
  "${OPT_FLAGS[@]}" \
  -sUSE_SDL=2 \
  -sUSE_SDL_IMAGE=2 \
  -sSDL2_IMAGE_FORMATS='["png","jpg"]' \
  -sUSE_SDL_TTF=2 \
  -sFULL_ES2=1 \
  -sMIN_WEBGL_VERSION=1 \
  -sMAX_WEBGL_VERSION=2 \
  -sWASM=1 \
  -sALLOW_MEMORY_GROWTH=1 \
  -sEXIT_RUNTIME=0 \
  -Wno-unused-label \
  -Wno-c99-extensions \
  "${SOURCES[@]}" \
  ${PRELOAD[@]+"${PRELOAD[@]}"} \
  -o "$OUT/th06.html"
set +x

echo ""
echo "Build OK -> $OUT/th06.{html,js,wasm}"
echo "Serve with:  cd '$OUT' && python3 -m http.server 8000"
echo "Then open:   http://localhost:8000/th06.html"
